"""build_table.py — 从 intent_config.json 生成快路径基表(只含已知命令, additive=False)

  python -m opencode_fastpath.build_table
  python -m opencode_fastpath.build_table --config <path> --table <path>
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from .fastpath import FastPath
from .pinyin import Encoder

ROOT = Path(__file__).resolve().parent.parent
OPEN_PREFIX = ("打开", "启动", "开一下", "运行", "上", "进入")


def entries_from_config(cfg: dict):
    out = []
    for a in cfg.get("apps", []):
        names = [a.get("name", "")] + list(a.get("aliases") or [])
        trig = [p + n for n in names if n for p in OPEN_PREFIX]
        out.append(("launch_app", a.get("name", ""), trig))
    for u in cfg.get("urls", []):
        names = [u.get("name", "")] + list(u.get("aliases") or [])
        trig = [p + n for n in names if n for p in OPEN_PREFIX]
        out.append(("open_url", u.get("name", ""), trig))
    for f in cfg.get("files", []):
        names = [f.get("name", "")] + list(f.get("aliases") or [])
        trig = [p + n for n in names if n for p in OPEN_PREFIX]
        out.append(("open_file", f.get("name", ""), trig))
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--config", default=str(ROOT / "intent_config.json"))
    ap.add_argument("--table", default=str(Path(__file__).resolve().parent / "table.json"))
    args = ap.parse_args()

    cfg = json.loads(Path(args.config).read_text(encoding="utf-8"))
    rows = entries_from_config(cfg)

    fp = FastPath(table_path=args.table, mode="off")
    fp.entries = []
    fp.enc = Encoder()
    n_trig = 0
    for intent, arg, trig in rows:
        if not arg or not trig:
            continue
        fp.install(intent, arg, trig, additive=False, markers={"source": "intent_config.json"})
        n_trig += len(trig)
    st = fp.stats()
    print(f"[OPENCODE] 基表生成完成: 条目 {len(fp.entries)}  触发器 {n_trig}"
          f"  音节 {len(fp.enc.ids)}  行(全串/前缀) {st['full']}/{st['prefix']}"
          f"  表体 {st['bytes']}B  → {args.table}")


if __name__ == "__main__":
    main()
